-- Learnings: what people and their agents learned, written for the next agent, with every
-- change kept so any of them can be undone. A learning is indexed the moment it is saved, as a
-- source of the knowledge base. See docs/knowledge.md, Learnings.

-- The fixed list a learning is filed under; docs/knowledge.md says what each one holds.
CREATE TYPE learning_category AS ENUM (
    'decision',
    'convention',
    'procedure',
    'pitfall',
    'reference',
    'environment',
    'people',
    'project',
    'incident'
);

CREATE TABLE learnings (
    -- Generated by the API (UUIDv7).
    id UUID PRIMARY KEY,
    -- The takeaway, on one line: the API trims it and collapses its whitespace before storing.
    title TEXT NOT NULL CHECK (char_length(title) BETWEEN 1 AND 300),
    -- Leads with the rule or decision, then when it applies and why.
    body TEXT NOT NULL CHECK (char_length(body) BETWEEN 1 AND 20000),
    category learning_category NOT NULL,
    -- What shows it is true: a command and its output, a link, a quote, a meeting.
    evidence TEXT NOT NULL CHECK (char_length(evidence) BETWEEN 1 AND 20000),
    -- The agent that acted for created_by when the learning was first saved: an MCP client, as
    -- `mcp:<client id>`, or NULL when the person saved it themselves.
    agent TEXT CHECK (agent ~ '^mcp:[^[:space:]]{1,255}$'),
    -- What that agent called itself when it saved, such as `Claude Code`. A client registers its
    -- own name, so it is a label, never an identity; `agent` is the identity.
    agent_name TEXT CHECK (char_length(agent_name) BETWEEN 1 AND 200),
    -- Soft delete: NULL while the learning is live. A deleted learning leaves the index and can
    -- be restored from its history.
    deleted_at TIMESTAMPTZ,
    created_by UUID NOT NULL REFERENCES users (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT learnings_agent_named_with_its_agent CHECK (agent IS NOT NULL OR agent_name IS NULL)
);

SELECT diesel_manage_updated_at('learnings');

-- Saving the same title again revises that learning, so a title names one learning, whatever
-- its case. Deleted learnings are included: saving a deleted learning's title again brings it
-- back revised, and restoring one never meets a live twin. lower() follows the database's
-- collation, whose changes `migrate run` rebuilds indexes for (docs/database.md, Collations).
CREATE UNIQUE INDEX learnings_title_unique ON learnings (lower(title));

-- The history of learnings, one entry per change, shaped like action_item_events: `data` holds
-- the values before and after, enough to show a change and to undo it.
CREATE TABLE learning_events (
    -- UUIDv7, so entries order as they were written.
    id UUID PRIMARY KEY,
    learning_id UUID NOT NULL REFERENCES learnings (id) ON DELETE CASCADE,
    -- `created`, `revised`, `deleted`, or `restored`. Text rather than an enum, as for
    -- action_item_events, so a later kind needs no enum migration.
    kind TEXT NOT NULL CHECK (kind ~ '^[a-z][a-z_]{0,63}$'),
    -- Who made the change. Every change to a learning is a person's, or a machine user's, so it
    -- references users rather than recording an actor as text.
    created_by UUID NOT NULL REFERENCES users (id),
    -- The agent that acted for them, as on learnings, and what it called itself.
    agent TEXT CHECK (agent ~ '^mcp:[^[:space:]]{1,255}$'),
    agent_name TEXT CHECK (char_length(agent_name) BETWEEN 1 AND 200),
    data JSONB NOT NULL CHECK (jsonb_typeof(data) = 'object'),
    created_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT learning_events_agent_named_with_its_agent CHECK (
        agent IS NOT NULL OR agent_name IS NULL
    )
);

CREATE INDEX learning_events_learning_id_idx ON learning_events (learning_id, id);

-- A learning is a source of the knowledge index: a column of its own, unique and cascading, as
-- every source is (docs/knowledge.md, Search).
ALTER TABLE knowledge_documents
    ADD COLUMN learning_id UUID UNIQUE REFERENCES learnings (id) ON DELETE CASCADE;

ALTER TABLE knowledge_documents DROP CONSTRAINT knowledge_documents_one_source;
ALTER TABLE knowledge_documents ADD CONSTRAINT knowledge_documents_one_source
    CHECK (num_nonnulls(timeline_record_id, learning_id) = 1);
